from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class M2mOperationResponseV1(SchemaObject):
    validation_errors = SchemaField(name="validation_errors", optional=True)
    error_message = SchemaField(name="error_message", optional=True)
    id = SchemaField(name="id", not_null=True)
    status = SchemaField(name="status", not_null=True)

    def __init__(self, validation_errors, error_message, id, status):
        self.validation_errors = validation_errors
        self.error_message = error_message
        self.id = id
        self.status = status

        super(M2mOperationResponseV1, self).__init__()
